    public static function refused(string $uid,int $message,int $account,object $f):array {$before=self::count('mail_attachments',['user_id'=>$uid]);$copies=self::count('mail_mcp_draft_copies',['target_account_id'=>$account]);$refused=false;try{Server::get('OCA\\Mail\\Service\\GuardedDraftImport')->preview($uid,$message,$account,null,self::fence($f));}catch(\Throwable){$refused=true;}return ['refused'=>$refused,'no_staging'=>$before===self::count('mail_attachments',['user_id'=>$uid])&&$copies===self::count('mail_mcp_draft_copies',['target_account_id'=>$account]),'source_retained'=>self::count('mail_messages',['id'=>$message])===1];}
