            $noEffects=$attachments===self::count('mail_attachments',['user_id'=>$uid])&&$drafts===self::count('mail_local_messages',['account_id'=>$account])&&$copies===self::count('mail_mcp_draft_copies',['target_account_id'=>$account]);
            $body=$reader->readBody($uid,$message,$f);$raw=$reader->readRaw($uid,$message,$f);$unchanged=$body['body_html']==='<img src="image.png">'&&str_contains($raw['bytes'],str_ends_with($mode,'language')?'Content-Language: en':'https://example.test/message/page.html');
            if(!str_contains($mode,'_single_'))$unchanged=$unchanged&&$reader->readAttachment($uid,$message,'2',$f)['bytes']==='aaa';
            return ['reader_refused'=>$readRefused,'import_refused'=>$importRefused,'no_effects'=>$noEffects,'other_reads_preserved'=>$unchanged,'source_retained'=>self::count('mail_messages',['id'=>$message])===1];
        }finally{if($id!==null)Server::get('OCA\\Mail\\Service\\DraftsService')->deleteMessage($uid,Server::get('OCA\\Mail\\Service\\DraftsService')->getMessage($id,$uid));self::query('mail_mcp_draft_copies',['operation_key'=>$key])->delete('mail_mcp_draft_copies')->executeStatement();}
