        $q=self::query('mail_messages',['id'=>$message]);$q->update('mail_messages')->set('tag_cache_generation',$q->createNamedParameter('43'))->executeStatement();$stale=$service->search($uid,[$box],'text',50,null,$f);
        $q=self::query('mail_messages',['id'=>$message]);$q->update('mail_messages')->set('tag_cache_generation',$q->createNamedParameter('42'))->executeStatement();
